"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type FocusEvent, type PointerEvent, type ReactNode, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for a hover fan. Pass `href` to make it a link, or `onSelect` to make it a button. */
export interface HoverFanProps {
  /** Names the stack, for example "Brand photos". It shows under the cards. */
  label: string;
  /** What the stack holds, back left, front, back right. Decorative: the label names the stack. */
  cards: [ReactNode, ReactNode, ReactNode];
  /** A short line under the label, for example "24 files". */
  detail?: string;
  href?: string;
  onSelect?: () => void;
  className?: string;
}

// The back cards overshoot once on the way out. The move changes no state, so a
// soft overshoot is allowed here; see docs/ui/hover-fan.md.
const FAN_OUT: Transition = { duration: 0.36, ease: [0.34, 1.5, 0.64, 1] };
// The way back is a plain ease-out: an overshoot on the return would cross the front card.
const FAN_IN: Transition = { duration: 0.24, ease: [0.22, 1, 0.36, 1] };
// The front card grows on a slower clock than the fan, and never overshoots.
const FRONT: Transition = { duration: 0.61, ease: [0.22, 1, 0.36, 1] };
const INSTANT: Transition = { duration: 0 };

// Where each back card rests and where it fans to. Lengths are rem.
const BACK = [
  { rest: { x: "-0.375rem", rotate: -5 }, fanned: { x: "-3.6rem", rotate: -14 } },
  { rest: { x: "0.375rem", rotate: 4 }, fanned: { x: "3.6rem", rotate: 10 } },
];

// Each card is 4.875rem square with a 0.75rem radius.
const CARD =
  "absolute left-1/2 top-2 -ml-9.75 grid size-19.5 place-items-center overflow-hidden rounded-xl border border-border bg-card text-muted-foreground shadow-sm";

// A tap also focuses the control. Only keyboard focus should hold the fan open.
function focusIsVisible(element: Element) {
  try {
    return element.matches(":focus-visible");
  } catch {
    // An engine without :focus-visible throws on the selector. Treat every focus as visible there.
    return true;
  }
}

/**
 * A small stack of three cards that fans out to show what it holds. It fans on
 * hover and on keyboard focus, and on touch only while it is pressed.
 */
export function HoverFan({ label, cards, detail, href, onSelect, className }: HoverFanProps) {
  const [hovered, setHovered] = useState(false);
  const [focused, setFocused] = useState(false);
  const [pressed, setPressed] = useState(false);
  const reduceMotion = useReducedMotion();
  const open = hovered || focused || pressed;
  const fanned = open && !reduceMotion;

  const [left, front, right] = cards;
  const content = (
    <>
      <span aria-hidden="true" className="relative block h-24 w-56">
        {[left, right].map((card, index) => (
          <motion.span
            key={index === 0 ? "left" : "right"}
            initial={false}
            animate={fanned ? BACK[index].fanned : BACK[index].rest}
            transition={reduceMotion ? INSTANT : fanned ? FAN_OUT : FAN_IN}
            className={CARD}
          >
            {card}
          </motion.span>
        ))}
        <motion.span
          initial={false}
          animate={{ scale: fanned ? 1.04 : 1 }}
          transition={reduceMotion ? INSTANT : FRONT}
          className={cn(CARD, "text-foreground shadow-md")}
        >
          {front}
        </motion.span>
      </span>
      <span className="flex flex-col items-center">
        <span
          className={cn(
            "text-sm font-medium motion-safe:transition-colors motion-safe:duration-150",
            open ? "text-foreground" : "text-muted-foreground",
          )}
        >
          {label}
        </span>
        {detail ? <span className="text-xs text-muted-foreground">{detail}</span> : null}
      </span>
    </>
  );

  const shared = {
    "data-open": open || undefined,
    // A touch has no hover: its synthetic one would stick until the next tap.
    onPointerEnter: (event: PointerEvent) => {
      if (event.pointerType !== "touch") setHovered(true);
    },
    onPointerLeave: () => {
      setHovered(false);
      setPressed(false);
    },
    onPointerDown: () => setPressed(true),
    onPointerUp: () => setPressed(false),
    onPointerCancel: () => setPressed(false),
    onFocus: (event: FocusEvent<HTMLElement>) => setFocused(focusIsVisible(event.currentTarget)),
    onBlur: () => setFocused(false),
    className: cn(
      "inline-flex cursor-pointer touch-manipulation flex-col items-center gap-2 rounded-2xl p-2 outline-none",
      "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
      className,
    ),
  };

  return href ? (
    <a href={href} onClick={onSelect} {...shared}>
      {content}
    </a>
  ) : (
    <button type="button" onClick={onSelect} {...shared}>
      {content}
    </button>
  );
}
